package com.bank.coupon;

import java.util.LinkedHashMap;
import java.util.Map;

class CouponKeyService {

    // Two passes: count into insertion-ordered map, then find first count==1.
    Character firstUnique(String code) {
        if (code == null || code.isEmpty()) return null;
        // LinkedHashMap preserves the order characters first appeared
        Map<Character, Integer> freq = new LinkedHashMap<>();
        for (char c : code.toCharArray()) {
            freq.merge(c, 1, Integer::sum);          // pass 1: count
        }
        for (Map.Entry<Character, Integer> e : freq.entrySet()) {
            if (e.getValue() == 1) {                 // pass 2: first with count 1
                return e.getKey();
            }
        }
        return null;                                 // no unique character
    }
}
